class UnitOfWork:
    def __init__(self):
        self._operations = []

    def register(self, operation, rollback):
        self._operations.append((operation, rollback))

    def commit(self):
        results = []
        for op, _ in self._operations:
            results.append(op())
        return results

    def rollback(self):
        for _, rb in reversed(self._operations):
            rb()

