from typing import Callable

class Middleware:
    def __init__(self):
        self._middlewares = []

    def add(self, middleware: Callable):
        self._middlewares.append(middleware)

    def execute(self, request, handler):
        def apply_middleware(index, req):
            if index < len(self._middlewares):
                return self._middlewares[index](req, lambda r: apply_middleware(index + 1, r))
            return handler(req)
        return apply_middleware(0, request)

