import weakref

class Event:
    def __init__(self):
        self._handlers = []

    def subscribe(self, handler):
        self._handlers.append(weakref.ref(handler))

    def emit(self, data):
        results = []
        dead_refs = []
        for ref in self._handlers:
            handler = ref()
            if handler:
                results.append(handler(data))
            else:
                dead_refs.append(ref)
        for ref in dead_refs:
            self._handlers.remove(ref)
        return results

