    def __init__(self, value: T):
        self.value = value
    def __repr__(self):
        return f'Leaf({self.value})'

class Node(Tree[T]):
    def __init__(self, left: Tree[T], right: Tree[T]):
        self.left = left
        self.right = right
    def __repr__(self):
        return f'Node({self.left}, {self.right})'

def cata(tree, leaf_func, node_func):
    if isinstance(tree, Leaf):
        return leaf_func(tree.value)
    elif isinstance(tree, Node):
        return node_func(
            cata(tree.left, leaf_func, node_func),
            cata(tree.right, leaf_func, node_func)
        )

tree = Node(
    Node(Leaf(1), Leaf(2)),
    Leaf(3)
)

result = cata(tree, lambda x: x, lambda l, r: l + r)
print(result)

from typing import TypeVar, Callable

T = TypeVar('T')
U = TypeVar('U')

class Writer(Generic[T]):
    def __init__(self, value: T, log: list[str]):
        self.value = value
        self.log = log

    @staticmethod
    def unit(value: T) -> 'Writer[T]':
        return Writer(value, [])

    def map(self, func: Callable[[T], U]) -> 'Writer[U]':
        return Writer(func(self.value), self.log)

    def flat_map(self, func: Callable[[T], 'Writer[U]']) -> 'Writer[U]':
        new_writer = func(self.value)
        return Writer(new_writer.value, self.log + new_writer.log)

    @staticmethod
    def tell(msg: str) -> 'Writer[None]':
        return Writer(None, [msg])

def add_logging(x: int) -> Writer[int]:
    return Writer(x, []).flat_map(
        lambda v: Writer.tell(f'Processing {v}').flat_map(
            lambda _: Writer(v + 10, []).flat_map(
                lambda result: Writer.tell(f'Result is {result}').map(
                    lambda _: result
                )
            )
        )
    )

result = add_logging(5)
print(result.value)
print(result.log)

from typing import TypeVar, Callable

T = TypeVar('T')
U = TypeVar('U')

class State(Generic[T, U]):
    def __init__(self, run: Callable[[T], tuple[U, T]]):
        self._run = run

    def map(self, func: Callable[[U], any]) -> 'State[T, any]':
        return State(lambda s: (func(self._run(s)[0]), self._run(s)[1]))

    def flat_map(self, func: Callable[[U], 'State[T, any]']) -> 'State[T, any]':
        def run(s):
            value, new_state = self._run(s)
            return func(value)._run(new_state)
        return State(run)

    @staticmethod
    def get() -> 'State[T, T]':
        return State(lambda s: (s, s))

    @staticmethod
    def put(new_state: T) -> 'State[T, None]':
        return State(lambda _: (None, new_state))

    def run(self, initial: T) -> tuple[U, T]:
        return self._run(initial)

program = State.get().flat_map(
    lambda s: State.put(s + 10).flat_map(
        lambda _: State.get().flat_map(
            lambda s2: State(lambda s: (s2 * 2, s))
        )
    )
)

print(program.run(5))

from typing import TypeVar, Generic
from dataclasses import dataclass

T = TypeVar('T')

@dataclass(frozen=True)
class ValueObject:
    pass

@dataclass(frozen=True)
class Money(ValueObject):
    amount: int
    currency: str

    def __add__(self, other: 'Money') -> 'Money':
        if self.currency != other.currency:
            raise ValueError(f'Currency mismatch: {self.currency} vs {other.currency}')
        return Money(self.amount + other.amount, self.currency)

    def __mul__(self, factor: int) -> 'Money':
        return Money(self.amount * factor, self.currency)

class DiscountCalculator:
    def calculate(self, price: Money, discount_percent: float) -> Money:
        discount_amount = int(price.amount * discount_percent)
        return Money(price.amount - discount_amount, price.currency)

calc = DiscountCalculator()
price = Money(100, 'USD')
result = calc.calculate(price, 0.15)
print(result)

from typing import TypeVar, Callable

T = TypeVar('T')

class Lazy(Generic[T]):
    def __init__(self, computation: Callable[[], T]):
        self._computation = computation
        self._evaluated = False
        self._value = None

    def force(self) -> T:
        if not self._evaluated:
            self._value = self._computation()
            self._evaluated = True
        return self._value

    def map(self, func: Callable[[T], any]) -> 'Lazy':
        return Lazy(lambda: func(self.force()))

    def flat_map(self, func: Callable[[T], 'Lazy']) -> 'Lazy':
        return Lazy(lambda: func(self.force()).force())

side_effects = []
lazy_value = Lazy(lambda: side_effects.append('evaluated') or 42)
print('Before force')
mapped = lazy_value.map(lambda x: x + 1)
print('After map, before force')
print(mapped.force())
print(side_effects)

from typing import TypeVar

T = TypeVar('T')

class NonEmptyList:
    def __init__(self, head, tail=None):
        self.head = head
        self.tail = tail if tail is not None else []

    def __iter__(self):
        yield self.head
        yield from self.tail

    def map(self, func):
        new_head = func(self.head)
        new_tail = [func(x) for x in self.tail]
        return NonEmptyList(new_head, new_tail)

    def fold(self, func, initial):
        result = func(initial, self.head)
        for item in self.tail:
            result = func(result, item)
        return result

    def __repr__(self):
        return f'NonEmptyList({list(self)})'

nel = NonEmptyList(1, [2, 3, 4, 5])
result = nel.map(lambda x: x * x).fold(lambda acc, x: acc + x, 0)
print(result)
